import django,os;os.environ.setdefault('DJANGO_SETTINGS_MODULE','backend.config.settings');django.setup();from backend.apps.trading.models import Signal,OpenPosition,Order;from django.utils import timezone;ago=timezone.now()-timezone.timedelta(hours=1);print('Sig(1h):',Signal.objects.filter(created_at__gte=ago).count());print('Active:',Signal.objects.filter(status='ACTIVE').count());print('Pos:',OpenPosition.objects.filter(is_deleted=False).count());print('Ord(1h):',Order.objects.filter(created_at__gte=ago).count())
